function renderLawTree(){
 if(!$("lawTree"))return;
 const q=($("treeSearch")?.value||"").trim(), pid=$("treeParent")?.value||"";
 const groups=LAW_TREE.groups.filter(g=>!pid||g.parentId===pid).map(g=>{
   const all=[...(g.children||[]),...(g.related||[])];
   const matched=all.filter(x=>!q||`${g.parent} ${x.name} ${x.basis}`.includes(q));
   const parentMatch=!q||g.parent.includes(q);
   if(!parentMatch&&!matched.length)return "";
   const child=matched.filter(x=>(g.children||[]).some(c=>c.id===x.id));
   const rel=matched.filter(x=>(g.related||[]).some(c=>c.id===x.id));
   return `<div class="treegroup"><div class="treeparent"><div><h3>${g.parent}</h3><div class="meta">母法</div></div><div class="tree-actions"><span class="badge red">母法</span><button class="chip ready" onclick="openLaw('${g.parentId}')">開啟母法</button></div></div>
      <div class="treebody">${child.length?`<div class="tree-section-title">直接子法／配套</div>${child.map(treeNode).join("")}`:""}${rel.length?`<div class="tree-section-title">相關獨立法律／其子法</div>${rel.map(treeNode).join("")}`:""}</div></div>`;
 }).join("");
 $("lawTree").innerHTML=groups||`<div class="empty"><b>查無法規</b><p>請調整母法或搜尋條件。</p></div>`;
}

