function idbOpen(){
 return new Promise((resolve,reject)=>{
   const req=indexedDB.open(YAMOL_DB,2);
   req.onupgradeneeded=()=>{
     const db=req.result;
     if(!db.objectStoreNames.contains(YAMOL_STORE))db.createObjectStore(YAMOL_STORE,{keyPath:"id"});
     if(!db.objectStoreNames.contains(NOTE_STORE))db.createObjectStore(NOTE_STORE,{keyPath:"id"});
   };
   req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);
 });
}
