async function readFileText(file){return await file.text()}
async function handleImportFiles(files){
 const meta={defaultSubject:$("yamolDefaultSubject").value,mode:$("yamolImportMode").value};
 const all=[];
 for(const f of [...files]){
   if(!/\.(html?|csv|json|txt)$/i.test(f.name))continue;
   try{const raw=await readFileText(f);if(/\.json$/i.test(f.name))await restoreLearningBackupIfPresent(raw);all.push(...parseImported(raw,f.name,meta));}
   catch(e){console.warn("import parse",f.name,e);}
 }
 IMPORT_PREVIEW=dedupePreview(all);renderImportPreview();
}
function questionCanUpgrade(oldQ,newQ){
 if(!oldQ)return false;
 return (
   (!(oldQ.answer?.length) && (newQ.answer?.length)) ||
   (!oldQ.explanation && !!newQ.explanation) ||
   (!oldQ.explanationHtml && !!newQ.explanationHtml) ||
   (!oldQ.lawId && !!newQ.lawId) ||
   (!oldQ.article && !!newQ.article) ||
   (oldQ.yamolCorrectRate==null && newQ.yamolCorrectRate!=null)
 );
}
function dedupePreview(rows){
 const seen=new Set(), existing=new Map(IMPORTED_QUESTIONS.map(x=>[x.id,x]));
 return rows.map(q=>{
   const oldQ=existing.get(q.id), repeated=seen.has(q.id);
   const isUpgrade=!repeated && questionCanUpgrade(oldQ,q);
   const isDuplicate=repeated || (!!oldQ && !isUpgrade);
   seen.add(q.id);
   return {...q,isDuplicate,isUpgrade};
 });
}
function previewStats(rows){
 return {parsed:rows.length,answer:rows.filter(x=>x.answer?.length).length,explain:rows.filter(x=>x.explanation).length,law:rows.filter(x=>x.lawId&&x.article).length,dup:rows.filter(x=>x.isDuplicate).length};
}
function renderImportPreview(){
 if(!$("importPreview"))return;
 const st=previewStats(IMPORT_PREVIEW);$("impParsed").textContent=st.parsed;$("impAnswer").textContent=st.answer;$("impExplain").textContent=st.explain;$("impLaw").textContent=st.law;$("impDuplicate").textContent=st.dup;
 $("previewBadge").textContent=st.parsed?`${st.parsed}題已解析`:"尚未解析";$("commitImport").disabled=!IMPORT_PREVIEW.some(x=>!x.isDuplicate);
 const q=($("previewSearch")?.value||"").trim(),status=$("previewStatus")?.value||"";
 const rows=IMPORT_PREVIEW.filter(x=>{
   const hay=`${x.stem} ${x.explanation||""} ${x.subject||""} ${x.lawId?lawName(x.lawId):""} ${x.article||""} ${(x.answer||[]).join("")}`;
   const okStatus=!status||(status==="ready"&&!x.isDuplicate)||(status==="nolaw"&&!x.lawId)||(status==="noanswer"&&!x.answer?.length);
   return (!q||hay.includes(q))&&okStatus;
 });
 $("importPreview").innerHTML=rows.slice(0,120).map((x,i)=>`<div class="import-item">
   <div class="row"><h4>${i+1}. ${esc(x.stem.slice(0,180))}${x.stem.length>180?"…":""}</h4><span class="badge ${x.isDuplicate?"amber":x.isUpgrade?"blue":"green"}">${x.isDuplicate?"重複":x.isUpgrade?"可修復":"可匯入"}</span></div>
   <div class="qmeta"><span class="badge yamol-badge">阿摩</span><span class="badge blue">${x.subject||"未分類"}</span>${x.lawId?`<span class="badge green">${lawName(x.lawId)}${x.article?" 第"+x.article+"條":""}</span>`:""} </div>
   <div class="import-answer">答案：${x.answer?.length?x.answer.join(""):"未辨識"}${x.yamolCorrectRate!=null?`　阿摩答對率：${x.yamolCorrectRate}%`:""}${x.myAnswer?.length?`　我的答案：${x.myAnswer.join("")}`:""}</div>
   ${x.explanation?`<div class="import-explain">${esc(x.explanation.slice(0,800))}${x.explanation.length>800?"…":""}</div>`:""}
   ${x.parserWarnings?.length?`<div class="import-warning">⚠ ${x.parserWarnings.join("；")}</div>`:""}
 </div>`).join("")||'<div class="empty"><b>沒有符合篩選的題目</b></div>';
}
async function commitYamolImport(){
 const rows=IMPORT_PREVIEW.filter(x=>!x.isDuplicate);
 if(!rows.length)return;
 const repaired=rows.filter(x=>x.isUpgrade).length, fresh=rows.length-repaired;
 await idbPutMany(rows);IMPORTED_QUESTIONS=await idbAll();IMPORT_PREVIEW=[];renderImportPreview();renderYamolLibrary();renderWarRoom();renderExamSources();
 $("importResult").innerHTML=`<div class="notice"><strong>處理完成：新增 ${fresh} 題${repaired?`、修復 ${repaired} 題`:""}。</strong> 修復會直接補上原本缺少的答案／詳解／法條資料，不必先清空題庫。</div>`;
}
