 const rows=Object.entries(byLaw).sort((a,b)=>b[1]-a[1]);
 $("yamolLibrary").innerHTML=rows.length?rows.slice(0,30).map(([k,n])=>`<div class="library-row"><span>${k}</span><b>${n}題</b></div>`).join(""):'<div class="empty"><b>尚未匯入</b><p>匯入後會依法條／科目統計。</p></div>';
