 const blob=new Blob([JSON.stringify({version:"1.5",exportedAt:new Date().toISOString(),questions:IMPORTED_QUESTIONS,questionNotes:notes,reviewFlags:getReviewFlags(),spacedReview:getSR(),dailyProgress:getDailyProgress(),dailyMinutes:Number(localStorage.getItem(DAILY_MINUTES_KEY)||45)},null,2)],{type:"application/json"});
 const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`LexCore_私人題庫與筆記備份_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
