function allQuestions(){
 const official=QUESTION_BANK.officialQuestions||[];
 const diag=QUESTION_BANK.diagnosticQuestions||DIAGNOSTIC_QUESTIONS;
 return [...official,...IMPORTED_QUESTIONS,...diag];
}
function normalizedAccepted(q){
 const raw=q.answerAccepted||[Array.isArray(q.answer)?q.answer.join(""):String(q.answer||"")];
 return raw.map(x=>String(x).replace(/\s/g,"").split("").sort().join(""));
}
function gradeQuestion(q,selected){
 const sel=[...selected].sort();
 const selectedKey=sel.join("");
 const accepted=normalizedAccepted(q);
 if(q.type==="single"){
   if(!sel.length)return {score:0,max:2,correct:false,loss:0,blank:true};
   const ok=accepted.includes(selectedKey);
   return {score:ok?2:-2/3,max:2,correct:ok,loss:ok?0:2/3,blank:false};
 }
 if(!sel.length)return {score:0,max:3,correct:false,loss:0,blank:true};
 const canonical=(accepted[0]||"").split("");
 let score=0;
 for(const o of ["A","B","C","D","E"]){
   const should=canonical.includes(o), did=sel.includes(o);
   score += should===did ? 0.6 : -0.6;
 }
 score=Math.round(score*10)/10;
 return {score,max:3,correct:accepted.includes(selectedKey),loss:Math.max(0,3-score),blank:false};
}
function selectedTrapTags(q,selected){
 const out=[];
 for(const o of selected||[]){
   if(!(q.answer||[]).includes(o))out.push(...(q.optionTags?.[o]||["錯誤選項判斷"]));
 }
 // correct option that user missed can also reveal trap
 for(const o of q.answer||[]){
   if(!(selected||[]).includes(o))out.push(...(q.optionTags?.[o]||[]));
 }
 return [...new Set(out)];
}
function startQuiz(){
 let qs=allQuestions(), source=$("quizSource").value, subject=$("quizSubject").value, count=Number($("quizCount").value||10);
 if(source!=="all")qs=qs.filter(q=>q.sourceType===source);
 if(subject)qs=qs.filter(q=>q.subject===subject);
 // Fisher-Yates
 qs=[...qs];for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}
 qs=qs.slice(0,Math.min(count,qs.length));
 if(!qs.length){
   $("quizArea").innerHTML=`<div class="empty"><b>目前沒有符合條件的題目</b><p>官方題庫需先讓 GitHub Actions 完成試題PDF同步；你可以先選「系統診斷題」。</p></div>`;
   return;
 }
 QUIZ={questions:qs,index:0,answers:{},confidence:{},startedAt:Date.now(),questionStart:Date.now(),finished:false};
 renderQuizQuestion();
}
function currentQuestion(){return QUIZ?.questions?.[QUIZ.index]}
function setConfidence(n){
 if(!QUIZ)return;QUIZ.confidence[currentQuestion().id]=n;
 document.querySelectorAll(".confbtn").forEach(b=>b.classList.toggle("active",Number(b.dataset.c)===n));
}
function captureCurrent(){
 if(!QUIZ)return;
 const q=currentQuestion();
 const selected=[...document.querySelectorAll('input[name="qopt"]:checked')].map(x=>x.value);
 QUIZ.answers[q.id]=selected;
 const prior=QUIZ._lastCapture||{};
 const elapsed=Math.max(1,Math.round((Date.now()-(prior[q.id]||QUIZ.questionStart))/1000));
 QUIZ._elapsed=QUIZ._elapsed||{};QUIZ._elapsed[q.id]=elapsed;
 QUIZ._lastCapture={...(QUIZ._lastCapture||{}),[q.id]:Date.now()};
}
function nextQuestion(dir){
 captureCurrent();
 const ni=QUIZ.index+dir;
 if(ni<0||ni>=QUIZ.questions.length)return;
 QUIZ.index=ni;QUIZ.questionStart=Date.now();renderQuizQuestion();
}
function renderQuizQuestion(){
 const q=currentQuestion();if(!q)return;
 const saved=QUIZ.answers[q.id]||[], conf=QUIZ.confidence[q.id]||0;
 $("quizArea").innerHTML=`<div class="qcard">
   <div class="qmeta"><span class="badge ${q.sourceType==="official"?"green":q.sourceType==="yamol"?"yamol-badge":"amber"}">${q.sourceType==="official"?`${q.year}官方歷屆`:q.sourceType==="yamol"?"我的阿摩錯題":"系統診斷題"}</span><span class="badge blue">${q.subject}</span><span class="badge ${q.type==="single"?"blue":"red"}">${q.type==="single"?"單選":"複選"}</span><span class="badge amber">${QUIZ.index+1}/${QUIZ.questions.length}</span></div>
   <div class="qstem">${q.stem}</div>
   <div>${Object.entries(q.options||{}).map(([k,v])=>`<label class="option"><input name="qopt" value="${k}" type="${q.type==="single"?"radio":"checkbox"}" ${saved.includes(k)?"checked":""}><b>${k}</b><span>${v}</span></label>`).join("")}</div>
   <div class="confrow"><span class="meta">信心度：</span><button class="confbtn ${conf===1?"active":""}" data-c="1" onclick="setConfidence(1)">1 猜的</button><button class="confbtn ${conf===2?"active":""}" data-c="2" onclick="setConfidence(2)">2 普通</button><button class="confbtn ${conf===3?"active":""}" data-c="3" onclick="setConfidence(3)">3 很確定</button></div>
   <div class="quiznav"><button class="btn" onclick="nextQuestion(-1)" ${QUIZ.index===0?"disabled":""}>上一題</button><div>${QUIZ.index===QUIZ.questions.length-1?`<button class="btn primary" onclick="finishQuiz()">交卷計分</button>`:`<button class="btn primary" onclick="nextQuestion(1)">下一題</button>`}</div></div>
 </div>`;
}

function fmtDateTime(iso){
 try{return new Date(iso).toLocaleString("zh-TW",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})}catch{return iso||""}
}
function plainExplanationHtml(text=""){
 const lines=cleanText(text).split(/\n+/).map(x=>x.trim()).filter(Boolean);
 if(!lines.length)return `<div class="empty"><b>目前沒有原始詳解</b><p>你仍可在下方加入自己的補充解析。</p></div>`;
 return `<div class="yamol-rich-fallback">${lines.map(line=>{
   if(/^(?:第\s*\d+(?:-\d+)?\s*條|.+法第\s*\d+)/.test(line))return `<h4>${esc(line)}</h4>`;
   if(/^[一二三四五六七八九十]+[、.．]|^\d+[、.．]/.test(line))return `<p><b>${esc(line)}</b></p>`;
   return `<p>${esc(line)}</p>`;
 }).join("")}</div>`;
}
function sourceExplanationHtml(q){
 if(q.explanationHtml)return `<div class="yamol-rich">${q.explanationHtml}</div>`;
 return plainExplanationHtml(q.explanation||"");
}
function confidenceLabel(n){return n===3?"很確定":n===2?"普通":n===1?"猜的":"未標"}
function optionReviewHtml(x){
 const correct=new Set(x.q.answer||[]), selected=new Set(x.selected||[]);
 return Object.entries(x.q.options||{}).map(([k,v])=>{
   const c=correct.has(k),s=selected.has(k);
   let cls="",state="";
   if(c&&s){cls="correct";state="✓ 選對";}
   else if(c&&!s){cls="missed";state="漏選正解";}
   else if(!c&&s){cls="wrong-picked";state="✕ 誤選";}
   else state="未選";
   return `<div class="review-option ${cls}"><div class="option-letter">${k}</div><div>${esc(v)}</div><div class="option-state">${state}</div></div>`;
 }).join("");
}
function questionPriorityText(x){
 if(!x.g.correct&&x.conf===3)return "高信心答錯：這通常不是粗心，而是目前理解模型可能有偏差，建議優先重讀法條／教材。";
 if(!x.g.correct&&x.conf===1)return "低信心答錯：先補基本規則，再用相似題建立辨識感。";
 if(x.g.correct&&x.conf===1)return "猜對不等於掌握：建議仍看一次詳解，確認判斷理由。";
 if(x.g.correct&&x.conf===3)return "高信心答對：可快速確認考點後略過。";
 return x.g.correct?"答對，但可利用解析確認自己理由與標準答案一致。":"答錯，建議先找出是哪個要件、數字或程序順序判斷錯誤。";
}
