async function saveQuestionNote(qid){
 const text=$(`noteText-${qid}`)?.value.trim();if(!text)return;
 const rec=await idbGetNote(qid), now=new Date().toISOString();
 const entry={
   id:NOTE_EDITING[qid]||`n-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,
   type:$(`noteType-${qid}`)?.value||"補充觀念",
   source:$(`noteSource-${qid}`)?.value.trim()||"",
   tags:($(`noteTags-${qid}`)?.value||"").split(/[,，、]/).map(x=>x.trim()).filter(Boolean),
   text,createdAt:now,updatedAt:now
 };
 if(NOTE_EDITING[qid]){
   const old=(rec.entries||[]).find(x=>x.id===NOTE_EDITING[qid]);
   if(old)entry.createdAt=old.createdAt||now;
   rec.entries=(rec.entries||[]).map(x=>x.id===NOTE_EDITING[qid]?entry:x);
 }else rec.entries=[...(rec.entries||[]),entry];
 await idbPutNote(rec);cancelQuestionNoteEdit(qid);renderQuestionNoteTimeline(qid,rec);
}
