function finishQuiz(){
 captureCurrent();let total=0,max=0,deduct=0,correct=0,confWrong=0,guessCorrect=0;const details=[];
 for(const q of QUIZ.questions){
   const selected=QUIZ.answers[q.id]||[], g=gradeQuestion(q,selected), conf=QUIZ.confidence[q.id]||0;
   total+=g.score;max+=g.max;deduct+=g.loss;if(g.correct)correct++;
   if(!g.correct&&conf===3)confWrong++;
   if(g.correct&&conf===1)guessCorrect++;
   const traps=g.correct?[]:selectedTrapTags(q,selected);
   const rec={
     id:`${Date.now()}-${q.id}`,at:new Date().toISOString(),questionId:q.id,sourceType:q.sourceType,year:q.year||null,
     subject:q.subject,lawId:q.lawId||null,article:q.article||null,tags:q.tags||[],trapTags:traps,
     type:q.type,selected,answer:q.answer||[],accepted:q.answerAccepted||null,
     score:g.score,max:g.max,loss:g.loss,correct:g.correct,blank:g.blank,
     confidence:conf,seconds:QUIZ._elapsed?.[q.id]||0
   };
   saveAttempt(rec);details.push({q,g,selected,conf,traps});
 }
 total=Math.round(total*10)/10;deduct=Math.round(deduct*10)/10;
 QUIZ.finished=true;
 const need=details.filter(x=>!x.g.correct||x.conf===1).length;
 $("quizArea").innerHTML=`<div class="qcard">
   <div class="row"><div><h2 style="margin:0">本次成績 ${total} / ${max}</h2><div class="meta">解析不只看錯題：猜對的題目也會列為「需要複習」</div></div><span class="badge ${total/max>=.75?"green":"red"}">${Math.round(total/max*100)}%</span></div>
   <div class="review-summary">
    <div class="review-kpi"><b>${correct}/${QUIZ.questions.length}</b><span>答對題數</span></div>
    <div class="review-kpi"><b>-${deduct}</b><span>倒扣／損失</span></div>
    <div class="review-kpi"><b>${confWrong}</b><span>高信心答錯</span></div>
    <div class="review-kpi"><b>${guessCorrect}</b><span>猜對但未掌握</span></div>
    <div class="review-kpi"><b>${need}</b><span>建議再複習</span></div>
   </div>
   <div class="review-toolbar"><button class="btn" onclick="setReviewCards('need')">只展開需要複習</button><button class="btn" onclick="setReviewCards('all')">全部展開</button><button class="btn" onclick="setReviewCards('none')">全部收合</button></div>
   <div class="review-list">${details.map((x,i)=>renderReviewCard(x,i)).join("")}</div>
   <div class="quiznav"><button class="btn" onclick="showPage('dashboard');renderWarRoom()">看戰情室</button><button class="btn primary" onclick="startQuiz()">再練一組</button></div>
 </div>`;
 setTimeout(hydrateReviewNotes,30);
}
function lawName(id){return DATA.laws.find(x=>x.id===id)?.name||id}

function warRows(){
 const attempts=getAttempts(), map={};
 for(const a of attempts){
   const key=a.lawId&&a.article?`${a.lawId}:${a.article}`:(a.tags?.[0]||a.subject||"其他");
   if(!map[key])map[key]={key,lawId:a.lawId,article:a.article,label:a.lawId?`${lawName(a.lawId)} 第${a.article}條`:key,n:0,wrong:0,loss:0,seconds:0,highConfWrong:0,last:null,traps:{},manualReview:0};
   const x=map[key];x.n++;if(!a.correct)x.wrong++;x.loss+=a.loss||0;x.seconds+=a.seconds||0;if(!a.correct&&a.confidence===3)x.highConfWrong++;
   x.last=a.at;
   for(const t of a.trapTags||[])x.traps[t]=(x.traps[t]||0)+1;
 }
 // Imported Yamol wrong questions are a weakness signal even before re-answering in LexCore.
 for(const q of IMPORTED_QUESTIONS){
   const key=q.lawId&&q.article?`${q.lawId}:${q.article}`:(q.subject||"阿摩未分類");
   if(!map[key])map[key]={key,lawId:q.lawId,article:q.article,label:q.lawId?`${lawName(q.lawId)} 第${q.article}條`:key,n:0,wrong:0,loss:0,seconds:0,highConfWrong:0,last:q.importedAt||null,traps:{},yamolWrong:0,yamolRateRisk:0,yamolRateN:0};
   map[key].yamolWrong=(map[key].yamolWrong||0)+(q.wrongHistoryCount||1);
   if(q.yamolCorrectRate!=null){
     map[key].yamolRateRisk=(map[key].yamolRateRisk||0)+(1-Math.max(0,Math.min(100,Number(q.yamolCorrectRate)))/100);
     map[key].yamolRateN=(map[key].yamolRateN||0)+1;
   }
 }
 // Explicit "再複習" flags are a manual weakness signal.
 const reviewFlags=getReviewFlags();
 for(const [qid,on] of Object.entries(reviewFlags)){
   if(!on)continue;
   const q=allQuestions().find(x=>x.id===qid);if(!q)continue;
   const key=q.lawId&&q.article?`${q.lawId}:${q.article}`:(q.subject||"手動再複習");
   if(!map[key])map[key]={key,lawId:q.lawId,article:q.article,label:q.lawId?`${lawName(q.lawId)} 第${q.article}條`:key,n:0,wrong:0,loss:0,seconds:0,highConfWrong:0,last:null,traps:{},manualReview:0};
   map[key].manualReview=(map[key].manualReview||0)+1;
 }
 // Add high-value amendments even if user has never answered them.
 for(const [key,m] of Object.entries(EXAM_META)){
   if(!map[key]){
     const [lawId,article]=key.split(":");
     map[key]={key,lawId,article,label:`${lawName(lawId)} 第${article}條`,n:0,wrong:0,loss:0,seconds:0,highConfWrong:0,last:null,traps:{}};
   }
 }
 const now=Date.now();
 for(const x of Object.values(map)){
   const meta=EXAM_META[x.key]||{score:3};
   const err=x.n?x.wrong/x.n:.35;
   const avgsec=x.n?x.seconds/x.n:0;
   const recency=x.last?Math.min(1,(now-new Date(x.last).getTime())/(1000*3600*24*14)):1;
   const conf=x.n?Math.min(1,x.highConfWrong/Math.max(1,x.n)):.15;
   const loss=Math.min(1,(x.loss||0)/Math.max(3,x.n*1.5));
   const slow=Math.min(1,avgsec/90);
   const heat=(meta.score||3)/5, yamol=Math.min(1,(x.yamolWrong||0)/3), manual=Math.min(1,(x.manualReview||0));
   const yamolRate=x.yamolRateN?Math.min(1,x.yamolRateRisk/x.yamolRateN):yamol;
   x.risk=Math.round(100*(.20*err+.14*loss+.13*conf+.06*slow+.07*recency+.13*heat+.09*yamol+.08*yamolRate+.10*manual));
   x.avgsec=Math.round(avgsec);
 }
 return Object.values(map).sort((a,b)=>b.risk-a.risk);
}
