const FONT_SCALE_KEY="lexcore-font-scale-v16";
const FONT_MIN=.8, FONT_MAX=1.5, FONT_STEP=.1;
let FONT_SCALE=Math.min(FONT_MAX,Math.max(FONT_MIN,Number(localStorage.getItem(FONT_SCALE_KEY)||1)||1));
let fontObserver=null;

function fontEligible(el){
 if(!el||el.nodeType!==1)return false;
 if(["SCRIPT","STYLE","SVG","PATH","IMG","IFRAME","CANVAS","BR","HR"].includes(el.tagName))return false;
 if(el.matches("input,select,textarea,button,option"))return true;
 return [...el.childNodes].some(n=>n.nodeType===3&&String(n.textContent||"").trim());
}
function rememberBaseFont(el,assumeScaled=false){
 if(!fontEligible(el)||el.dataset.lexcoreBaseFont)return;
 const size=parseFloat(getComputedStyle(el).fontSize);
 if(!Number.isFinite(size)||size<=0)return;
 let base=size;
 if(assumeScaled&&FONT_SCALE!==1){
   const parent=el.parentElement;
   const psize=parent?parseFloat(getComputedStyle(parent).fontSize):NaN;
   // If the size is inherited from an already-scaled parent, undo the scale.
   if(Number.isFinite(psize)&&Math.abs(size-psize)<.15)base=size/FONT_SCALE;
 }
 el.dataset.lexcoreBaseFont=String(base);
}
function applyFontTo(el){
 rememberBaseFont(el,true);
 const base=Number(el?.dataset?.lexcoreBaseFont);
 if(Number.isFinite(base))el.style.fontSize=`${Math.round(base*FONT_SCALE*100)/100}px`;
}
function scanFontNodes(root=document,initial=false){
 const list=[];
 if(root.nodeType===1)list.push(root);
 if(root.querySelectorAll)list.push(...root.querySelectorAll("*"));
 if(initial)list.forEach(el=>rememberBaseFont(el,false));
 list.forEach(applyFontTo);
}
function syncFontUI(){
 const pct=Math.round(FONT_SCALE*100);
 if($("fontPercent"))$("fontPercent").textContent=`${pct}%`;
 if($("fontDown"))$("fontDown").classList.toggle("font-limit",FONT_SCALE<=FONT_MIN+.001);
 if($("fontUp"))$("fontUp").classList.toggle("font-limit",FONT_SCALE>=FONT_MAX-.001);
}
function sendFontScaleToPromotion(){
 try{
   const f=$("promotionFrame");
   f?.contentWindow?.postMessage({type:"lexcore-font-scale",scale:FONT_SCALE},"*");
   f?.contentWindow?.setPromotionFontScale?.(FONT_SCALE);
 }catch(e){}
}
function setFontScale(value){
 const next=Math.min(FONT_MAX,Math.max(FONT_MIN,Math.round(value*10)/10));
 FONT_SCALE=next;
 localStorage.setItem(FONT_SCALE_KEY,String(FONT_SCALE));
 document.querySelectorAll("[data-lexcore-base-font]").forEach(applyFontTo);
 syncFontUI();
 sendFontScaleToPromotion();
}
function setupFontScale(){
 // Capture the current design sizes before any scaling.
 scanFontNodes(document,true);
 setFontScale(FONT_SCALE);
 if($("fontDown"))$("fontDown").onclick=()=>setFontScale(FONT_SCALE-FONT_STEP);
 if($("fontUp"))$("fontUp").onclick=()=>setFontScale(FONT_SCALE+FONT_STEP);
 if($("fontReset"))$("fontReset").onclick=()=>setFontScale(1);
 if(fontObserver)fontObserver.disconnect();
 fontObserver=new MutationObserver(muts=>{
   for(const m of muts)for(const n of m.addedNodes)if(n.nodeType===1)scanFontNodes(n,false);
 });
 fontObserver.observe(document.body,{childList:true,subtree:true});
 // Optional keyboard shortcuts inside LexCore: Alt + / Alt -
 document.addEventListener("keydown",e=>{
   if(!e.altKey)return;
   if(e.key==="+"||e.key==="="){e.preventDefault();setFontScale(FONT_SCALE+FONT_STEP);}
   if(e.key==="-"){e.preventDefault();setFontScale(FONT_SCALE-FONT_STEP);}
   if(e.key==="0"){e.preventDefault();setFontScale(1);}
 });
}

